routinesUI <- function(id) {
 ns<-NS(id);tagList(tags$h2('Small things that keep life moving.'),tags$p(class='lead','Protect hobbies and personal time. Keep flexible chores separate from work.'),
 section('Hobbies & personal time',selectInput(ns('hobby_selected'),'Choose a recurring personal activity',NULL),textInput(ns('hobby_title'),'Activity name',placeholder='e.g. Climbing, reading, time with friends'),checkboxGroupInput(ns('hobby_days'),'Repeat on',setNames(1:7,c('Mon','Tue','Wed','Thu','Fri','Sat','Sun')),inline=TRUE),fluidRow(column(6,textInput(ns('hobby_start'),'Starts (HH:MM)','18:00')),column(6,textInput(ns('hobby_end'),'Ends (HH:MM)','20:00'))),actionButton(ns('hobby_save'),'Save personal time',class='btn-primary'),actionButton(ns('hobby_new'),'New activity',class='btn-quiet'),actionButton(ns('hobby_delete'),'Delete selected activity',class='btn-danger-soft'),tags$p(class='hint','Recurring activities use 15-minute steps and appear automatically in Calendar as protected time. End before start crosses midnight. Each saved weekday is an occurrence you can edit separately. Plan preferences controls whether protected time stays blocked.')),
 section('Daily & weekly chores',selectInput(ns('selected'),'Choose a chore',NULL),textInput(ns('title'),'What needs doing?'),radioButtons(ns('period'),'Repeat',c('Daily','Weekly'),inline=TRUE),numericInput(ns('minutes'),'Allow about this many minutes',10,min=0,max=1440,step=5),dateInput(ns('start'),'Start date',Sys.Date()),checkboxInput(ns('active'),'Active',TRUE),actionButton(ns('save'),'Save chore',class='btn-primary'),actionButton(ns('new'),'New chore',class='btn-quiet'),actionButton(ns('delete'),'Delete chore',class='btn-danger-soft'),tags$p(class='hint','Delete retires a chore and keeps its completion history. No fixed calendar slot is required. Weekly chores become more visible near Sunday. Their estimated time is allowed for in reflection capacity.')))
}
routinesServer <- function(id,state,commit)moduleServer(id,function(input,output,session){
 editing<-reactiveVal('');hobby_editing<-reactiveVal('')
 observe({b<-state()$blocks;b<-b[b$kind=='Protected',,drop=FALSE];choices<-if(nrow(b))setNames(b$id,paste(c('Mon','Tue','Wed','Thu','Fri','Sat','Sun')[b$day],b$title,fmt_hour(b$start)))else character();updateSelectInput(session,'hobby_selected',choices=c('New personal activity'='',choices),selected=if(isolate(hobby_editing())%in%b$id)isolate(hobby_editing())else isolate(input$hobby_selected))})
 observeEvent(input$hobby_selected,{id<-input$hobby_selected %||% '';hobby_editing(id);if(nzchar(id)){b<-state()$blocks[match(id,state()$blocks$id),];updateTextInput(session,'hobby_title',value=b$title);updateCheckboxGroupInput(session,'hobby_days',selected=b$day);updateTextInput(session,'hobby_start',value=fmt_hour(b$start));updateTextInput(session,'hobby_end',value=fmt_hour(b$end))}})
 observeEvent(input$hobby_new,{hobby_editing('');updateSelectInput(session,'hobby_selected',selected='');updateTextInput(session,'hobby_title',value='');updateCheckboxGroupInput(session,'hobby_days',selected=character())})
 observeEvent(input$hobby_save,{tryCatch({before<-state();old<-hobby_editing();s<-save_personal_commitment(before,old,input$hobby_title,input$hobby_days,calendar_clock(input$hobby_start),calendar_clock(input$hobby_end));target<-if(nzchar(old))old else head(setdiff(s$blocks$id,before$blocks$id),1);commit(s);hobby_editing(target);updateSelectInput(session,'hobby_selected',selected=target)},error=notify_error)})
 observeEvent(input$hobby_delete,{id<-hobby_editing();req(nzchar(id));s<-append_archive(state(),'blocks',id);commit_safely(commit,s);hobby_editing('')})
 observe({d<-state()$chores;d$title<-paste0(d$title,ifelse(d$active,'',' (retired)'));updateSelectInput(session,'selected',choices=c('New chore'='',choices_id(d)),selected=isolate(input$selected))})
 observeEvent(input$selected,{id<-input$selected %||% '';editing(id);if(nzchar(id)){r<-state()$chores[match(id,state()$chores$id),];updateTextInput(session,'title',value=r$title);updateRadioButtons(session,'period',selected=r$period);updateNumericInput(session,'minutes',value=r$minutes);updateDateInput(session,'start',value=r$start_date);updateCheckboxInput(session,'active',value=r$active)}})
 observeEvent(input$new,{editing('');updateSelectInput(session,'selected',selected='');updateTextInput(session,'title',value='');updateCheckboxInput(session,'active',value=TRUE)})
 observeEvent(input$save,{tryCatch({s<-state();id<-if(nzchar(editing()))editing()else next_id('ch',s$chores$id);r<-data.frame(id=id,title=trimws(input$title),period=input$period,minutes=input$minutes,start_date=as.character(input$start),active=isTRUE(input$active));i<-match(id,s$chores$id);if(is.na(i))s$chores<-rbind(s$chores,r)else s$chores[i,]<-r;commit(s);editing(id)},error=notify_error)})
 observeEvent(input$delete,{s<-state();id<-editing();req(nzchar(id));s$chores$active[s$chores$id==id]<-FALSE;commit_safely(commit,s);editing('')})
})
choresTodayUI <- function(id)tagList(section('Daily chores',uiOutput(NS(id)('daily'))),section('This week’s chores',uiOutput(NS(id)('weekly'))))
choresTodayServer <- function(id,state,commit,controls)moduleServer(id,function(input,output,session){
 checklist<-function(period) {
  s<-state();today<-controls$today();c<-s$chores[s$chores$active&s$chores$period==period&s$chores$start_date<=as.character(today),,drop=FALSE]
  if(!nrow(c))return(tags$p(class='empty-hint',paste('No',tolower(period),'chores. Add some in Plan → Personal & chores.')))
  tagList(lapply(seq_len(nrow(c)),function(i){done<-chore_done(s,c$id[i],today);soon<-period=='Weekly'&&as.integer(format(today,'%u'))>=5&&!done
   tags$div(class=paste('chore-row',if(done)'is-complete'else if(soon)'needs-attention'else''),tags$button(type='button',class='chore-check','aria-pressed'=tolower(as.character(done)),'aria-label'=paste(if(done)'Mark unfinished:'else'Mark done:',c$title[i]),onclick=sprintf("Shiny.setInputValue('%s','%s',{priority:'event'})",session$ns('toggle'),c$id[i]),icon(if(done)'square-check'else'square')),tags$span(c$title[i]),tags$small(paste(c$minutes[i],'min')),if(soon)tags$small('Still open this week'))}))
 }
 output$daily<-renderUI(checklist('Daily'));output$weekly<-renderUI(checklist('Weekly'))
 observeEvent(input$toggle,commit_safely(commit,toggle_chore(state(),input$toggle,controls$today())))
})
categoryPreferencesUI <- function(id) {
 ns<-NS(id);section('Make priorities your own',tags$p('Consequences and personal meaning always stay. Choose which other categories you use, or create your own. Disabling a category keeps its saved task ratings.'),uiOutput(ns('list')),actionButton(ns('save'),'Save category preferences',class='btn-primary'),textInput(ns('label'),'New category name',placeholder='e.g. Learning, health, creative growth'),numericInput(ns('weight'),'Weight in Balanced priorities',.1,min=0,max=1,step=.05),actionButton(ns('add'),'Add category',class='btn-quiet'),tags$p(class='hint','Each enabled category also becomes its own decision lens. Balanced keeps urgency, consequences, income, contract balance and personal meaning, then adds the enabled category weights.'))
}
categoryPreferencesServer <- function(id,state,commit,controls)moduleServer(id,function(input,output,session){
 output$list<-renderUI({d<-state()$categories;tagList(lapply(seq_len(nrow(d)),function(i)fluidRow(column(2,checkboxInput(session$ns(paste0('enabled_',d$id[i])),'Use',d$enabled[i])),column(5,textInput(session$ns(paste0('label_',d$id[i])),'Category name',d$label[i])),column(5,numericInput(session$ns(paste0('weight_',d$id[i])),'Balanced weight',d$weight[i],min=0,max=1,step=.05)))))})
 observeEvent(input$save,{s<-state();for(i in seq_len(nrow(s$categories))){id<-s$categories$id[i];s$categories$enabled[i]<-isTRUE(input[[paste0('enabled_',id)]]);s$categories$label[i]<-trimws(input[[paste0('label_',id)]] %||% s$categories$label[i]);s$categories$weight[i]<-input[[paste0('weight_',id)]] %||% s$categories$weight[i]};if(!controls$strategy()%in%decision_lenses(s)){s$settings$plan_strategy<-'Balanced';controls$set_strategy('Balanced')};commit_safely(commit,s)})
 observeEvent(input$add,{tryCatch({label<-trimws(input$label %||% '');if(!nzchar(label))stop('Name your category.');s<-state();if(tolower(label)%in%tolower(c(s$categories$label,'Consequences','Personal meaning')))stop('This category already exists.');id<-next_id('category',s$categories$id);s$categories<-rbind(s$categories,data.frame(id=id,label=label,enabled=TRUE,weight=input$weight));commit(s);updateTextInput(session,'label',value='')},error=notify_error)})
})
task_category_fields <- function(s,ns,task_id='') {
 d<-s$categories[s$categories$enabled,,drop=FALSE];t<-s$tasks[s$tasks$id==task_id,,drop=FALSE]
 tagList(lapply(seq_len(nrow(d)),function(i){v<-if(nrow(t))category_scores(s,t,d$id[i])else 2;numericInput(ns(paste0('f_category_',d$id[i])),paste0(d$label[i],' (0–5)'),v,min=0,max=5)}))
}
